// Launcher controls and guided setup.
function populateSettings(){const p=readPrefs();$('#launchmode').value=p.launch;$('#tabtitle').value=p.title;$('#tabicon').value=p.icon;$('#customicon').value=p.customIcon;$('#invisible').checked=p.invisible;$('#reflection').checked=p.reflection;$('#panicenabled').checked=p.panicEnabled;$('#panicurl').value=p.panicUrl;$('#customiconrow').hidden=p.icon!=='custom'}
$('#settingsview').onclick=()=>{populateSettings();$('#settingsfeedback').textContent='';$('#settings').showModal()};$('#tabicon').onchange=()=>$('#customiconrow').hidden=$('#tabicon').value!=='custom';
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{const preset=b.dataset.preset;$('#tabtitle').value={arcade:'Pixel Arcade',notes:'Notes',google:'Google',sentral:'Sentral'}[preset];$('#tabicon').value=preset;$('#customiconrow').hidden=true});
$('#settingsform').onsubmit=e=>{e.preventDefault();const p={launch:$('#launchmode').value,title:$('#tabtitle').value.trim()||'Pixel Arcade',icon:$('#tabicon').value,customIcon:$('#customicon').value,invisible:$('#invisible').checked,reflection:$('#reflection').checked,panicEnabled:$('#panicenabled').checked,panicUrl:safeHttp($('#panicurl').value)};if(!p.panicUrl){$('#settingsfeedback').textContent='Enter a valid http or https quick-switch URL.';return}if(p.icon==='custom'&&!safeHttp(p.customIcon)){$('#settingsfeedback').textContent='Enter a valid http or https icon URL.';return}try{localStorage.setItem('px-settings',JSON.stringify(p));applyPrivacy();$('#settingsfeedback').textContent='Saved. New blank tabs use these settings.'}catch{$('#settingsfeedback').textContent='Browser storage is unavailable. Settings could not save.'}};
$('#resetsettings').onclick=()=>{localStorage.removeItem('px-settings');populateSettings();applyPrivacy();$('#settingsfeedback').textContent='Defaults restored.'};$('#tutorialview').onclick=()=>$('#tutorial').showModal();$('#tutorialdone').onclick=()=>{$('#tutorial').close();try{localStorage.setItem('px-tutorial-seen','1')}catch{}};$('#blankhub').onclick=()=>openBlank();$('#blankgame').onclick=()=>{if(current&&openBlank(current.id))player.close()};

if(inBlankShell){$('#blankhub').textContent='Open another blank tab ↗'}

$('#tutorial').addEventListener('close',()=>{try{localStorage.setItem('px-tutorial-seen','1')}catch{}});

window.pixelResumePendingGame=function(){const g=games.find(g=>g.id===window.pixelPendingGameId);window.pixelPendingGameId='';if(!g)return false;openGame(g,true);return true};
